                {linkLabel}
                <ChevronRight className="size-4" />
              </Link>
            )}
            <ChartDownloadButton title={title} description={description} />
          </div>
        </div>
        {alignToEnd ? <div className="mt-auto">{children}</div> : children}
      </section>
    </ChartExportProvider>
  )
}

