import { StatusBadge } from "@/components/overview/status-badge"
import { formatInteger, formatPercent } from "@/lib/format"
import { ChartExportData } from "@/components/export/chart-export-provider"
import { measuresTable } from "@/lib/export/chart-table"

export type RankingRow = {
  label: string
  value: number
  detail: string
  // Optional uptime, shown as a small badge.
  uptime?: number | null
}

type RankingListProps = {
  rows: RankingRow[]
  // Shown after each value, for example "vehicles" or "kg".
  valueLabel: string
  emptyText?: string
}

// The ranked list with bars. Used by the plain ranking card and the one with a switch.
export function RankingList({
  rows,
  valueLabel,
  emptyText = "No fills in this period.",
}: RankingListProps) {
  const largest = Math.max(...rows.map((row) => row.value), 1)

  if (rows.length === 0) {
    return (
      <>
        <ChartExportData table={measuresTable([])} />
        <p className="text-sm text-muted-foreground">{emptyText}</p>
      </>
    )
  }

  return (
    <>
      <ChartExportData table={measuresTable(rows.map((row) => [
        row.label,
        `${formatInteger(row.value)} ${valueLabel}${row.detail ? ` · ${row.detail}` : ""}${row.uptime == null ? "" : ` · Uptime ${formatPercent(row.uptime)}`}`,
      ]))} />
      <ol data-export-target className="flex flex-col gap-4">
        {rows.map((row, index) => (
          <li key={row.label}>
            <div className="flex items-baseline justify-between gap-3">
              <p className="min-w-0 truncate text-sm font-medium">
                <span className="mr-2 text-muted-foreground tabular-nums">{index + 1}</span>
                {row.label}
              </p>
              <p className="shrink-0 text-sm font-semibold tabular-nums">
                {formatInteger(row.value)}{" "}
                <span className="font-normal text-muted-foreground">{valueLabel}</span>
              </p>
            </div>
            <div className="mt-1.5 h-2 overflow-hidden rounded-full bg-foreground/10">
              <div
                className="h-full rounded-full bg-primary"
                style={{ width: `${(row.value / largest) * 100}%` }}
              />
            </div>
            <div className="mt-1.5 flex items-center justify-between gap-2">
              <p className="text-xs text-muted-foreground">{row.detail}</p>
              {row.uptime !== undefined && row.uptime !== null && (
                <StatusBadge tone={row.uptime >= 90 ? "good" : "warning"}>
                  Uptime {formatPercent(row.uptime)}
                </StatusBadge>
              )}
            </div>
          </li>
        ))}
      </ol>
    </>
  )
}

"use client"

import { useState } from "react"

import { DashboardPanel } from "@/components/dashboard-panel"
import { RankingList, type RankingRow } from "@/components/overview/ranking-list"

export type RankingMetric = {
  key: string
  // Text on the switch button, for example "By vehicles".
  label: string
  // Card description while this metric is selected.
  description: string
  // Unit shown after each value.
  valueLabel: string
}

export type ToggleRankingRow = {
  label: string
  // One number and one detail line for every metric key.
  values: Record<string, number>
  details: Record<string, string>
  uptime?: number | null
}

type RankingToggleCardProps = {
  title: string
  metrics: RankingMetric[]
  rows: ToggleRankingRow[]
  href?: string
  linkLabel?: string
  // "header" puts the switch at the top right of the card. "below" (the default)
  // puts it above the list, which suits narrow cards that also have a link.
  togglePlacement?: "header" | "below"
}

// A ranking card with a switch to rank by another measure (vehicles or gas sold).
// The switch is hidden when only one measure is available.
export function RankingToggleCard({
  title,
  metrics,
  rows,
  href,
  linkLabel,
  togglePlacement = "below",
}: RankingToggleCardProps) {
  const [metricKey, setMetricKey] = useState(metrics[0].key)
  const metric = metrics.find((candidate) => candidate.key === metricKey) ?? metrics[0]

  const rankedRows: RankingRow[] = rows
    .map((row) => ({
      label: row.label,
      value: row.values[metric.key] ?? 0,
      detail: row.details[metric.key] ?? "",
      uptime: row.uptime,
    }))
    .sort((a, b) => b.value - a.value)

  const toggle =
    metrics.length > 1 ? (
      <div
        role="group"
        aria-label="Rank by"
        className="inline-flex rounded-lg bg-background/60 p-1"
      >
        {metrics.map((option) => (
          <button
            key={option.key}
            type="button"
            aria-pressed={option.key === metric.key}
            onClick={() => setMetricKey(option.key)}
            className={`rounded-md px-3 py-1 text-sm font-medium whitespace-nowrap transition-colors ${
              option.key === metric.key
                ? "bg-primary text-primary-foreground shadow-sm ring-1 ring-primary/40"
                : "text-muted-foreground hover:text-foreground"
            }`}
          >
            {option.label}
          </button>
        ))}
      </div>
    ) : null

  return (
    <DashboardPanel
      title={title}
      description={metric.description}
      href={href}
      linkLabel={linkLabel}
      action={togglePlacement === "header" ? toggle : undefined}
    >
      {togglePlacement === "below" && toggle && <div className="mb-4">{toggle}</div>}
      <RankingList rows={rankedRows} valueLabel={metric.valueLabel} />
    </DashboardPanel>
  )
}

